:root {
  --color-bg: #2d1b2e;
  --color-card: #f5eedc;
  --color-dark: #1b101c;
  --color-primary: #3d7d52;
  --color-primary-hover: #4e9d67;
  --color-accent: #c44536;
  --color-accent-hover: #dd5645;
  --font-stack: 'Courier New', Courier, monospace;
}

[hidden] {
  display: none !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  background-image:
    linear-gradient(45deg, #241424 25%, transparent 25%),
    linear-gradient(-45deg, #241424 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #241424 75%),
    linear-gradient(-45deg, transparent 75%, #241424 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  font-family: var(--font-stack);
  color: var(--color-dark);
}

.card {
  background: var(--color-card);
  width: 100%;
  max-width: 420px;
  padding: 24px;
  border: 4px solid var(--color-dark);
  box-shadow:
    8px 8px 0 0 var(--color-dark),
    inset -4px -4px 0 0 #d9cca9,
    inset 4px 4px 0 0 #fffdf7;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.pixel-cup {
  width: 32px;
  height: 28px;
  background: #3d7d52;
  position: relative;
  box-shadow:
    -4px 4px 0 0 var(--color-dark),
    4px 4px 0 0 var(--color-dark),
    0 8px 0 0 var(--color-dark),
    6px 0 0 0 #3d7d52,
    10px 4px 0 0 var(--color-dark),
    10px 12px 0 0 var(--color-dark),
    6px 16px 0 0 var(--color-dark);
  margin-bottom: 8px;
}

.title {
  font-size: 24px;
  letter-spacing: 2px;
  font-weight: 900;
  text-transform: uppercase;
}

.section-label {
  font-size: 16px;
  font-weight: bold;
  margin-bottom: 10px;
}

.preset-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pixel-btn {
  font-family: var(--font-stack);
  font-size: 16px;
  font-weight: bold;
  background: #ffffff;
  color: var(--color-dark);
  border: 3px solid var(--color-dark);
  padding: 10px 14px;
  cursor: pointer;
  box-shadow: 4px 4px 0 0 var(--color-dark);
  outline: none;
  transition: none;
  text-align: center;
}

.pixel-btn:hover:not(:disabled) {
  background: #f0ede4;
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 0 var(--color-dark);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--color-dark);
  outline-offset: 3px;
}

.pixel-btn:active:not(:disabled) {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 0 var(--color-dark);
}

.preset-btn.is-active {
  background: var(--color-primary);
  color: #ffffff;
}

.pixel-btn:disabled {
  background: #d4cfc1;
  color: #79756b;
  cursor: not-allowed;
  box-shadow: 2px 2px 0 0 #79756b;
  border-color: #79756b;
}

.display-panel {
  background: #ffffff;
  border: 3px solid var(--color-dark);
  padding: 20px;
  text-align: center;
  box-shadow: inset 4px 4px 0 0 #dfd9c7;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 130px;
}

.timer-display {
  font-size: 48px;
  font-weight: 900;
  letter-spacing: 3px;
}

.status-message {
  margin-top: 10px;
  font-size: 18px;
  font-weight: bold;
  color: var(--color-accent);
  animation: pixelPulse 1s steps(2, start) infinite;
}

@keyframes pixelPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.2; }
}

.controls {
  display: flex;
  gap: 12px;
}

.action-btn {
  flex: 1;
  padding: 12px;
}

.start-btn {
  background: var(--color-primary);
  color: #ffffff;
}

.start-btn:hover:not(:disabled) {
  background: var(--color-primary-hover);
}

.cancel-btn {
  background: var(--color-accent);
  color: #ffffff;
}

.cancel-btn:hover:not(:disabled) {
  background: var(--color-accent-hover);
}

document.addEventListener('DOMContentLoaded', () => {
  let selectedSeconds = 120;
  let remainingSeconds = 120;
  let timerInterval = null;
  let isRunning = false;

  const timerDisplay = document.getElementById('timerDisplay');
  const statusMessage = document.getElementById('statusMessage');
  const startBtn = document.getElementById('startBtn');
  const cancelBtn = document.getElementById('cancelBtn');
  const presetButtons = document.querySelectorAll('.preset-btn');

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    const paddedSeconds = seconds < 10 ? `0${seconds}` : `${seconds}`;
    return `${minutes}:${paddedSeconds}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);
  }

  function selectPreset(button) {
    if (isRunning) return;

    presetButtons.forEach(btn => {
      btn.classList.remove('is-active');
      btn.setAttribute('aria-pressed', 'false');
    });

    button.classList.add('is-active');
    button.setAttribute('aria-pressed', 'true');

    selectedSeconds = parseInt(button.dataset.time, 10);
    remainingSeconds = selectedSeconds;
    statusMessage.hidden = true;
    updateDisplay();
  }

  function startTimer() {
    if (isRunning) return;

    if (remainingSeconds <= 0) {
      remainingSeconds = selectedSeconds;
    }

    isRunning = true;
    statusMessage.hidden = true;
    startBtn.disabled = true;
    cancelBtn.disabled = false;
    presetButtons.forEach(btn => (btn.disabled = true));

    timerInterval = setInterval(() => {
      remainingSeconds -= 1;
      updateDisplay();

      if (remainingSeconds <= 0) {
        clearInterval(timerInterval);
        timerInterval = null;
        isRunning = false;
        statusMessage.hidden = false;
        startBtn.disabled = false;
        cancelBtn.disabled = true;
        presetButtons.forEach(btn => (btn.disabled = false));
      }
    }, 1000);
  }

  function cancelTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }

    isRunning = false;
    remainingSeconds = selectedSeconds;
    updateDisplay();
    statusMessage.hidden = true;
    startBtn.disabled = false;
    cancelBtn.disabled = true;
    presetButtons.forEach(btn => (btn.disabled = false));
  }

  presetButtons.forEach(btn => {
    btn.addEventListener('click', () => selectPreset(btn));
  });

  startBtn.addEventListener('click', startTimer);
  cancelBtn.addEventListener('click', cancelTimer);

  updateDisplay();
});
